function _CA.PreloadTech(p7, p8)
	local v6749 = _CA.t364[p7]

	if p8 then
		v6749 = _CA.t364[p8.BossName][p7]
	end

	if not v6749 then
		return
	end

	local t367: {[any]: any} = {}

	for _, v in pairs(v6749) do
		local s1: string = "rbxassetid://" .. v.Image

		table.insert(t367, s1)

		if v.ScaleType == "Slice" then
			_CA.preloadSlice(s1, v.SliceCenter, v.SliceScale)
		end

		if v.SpritesheetAnimations then
			for _, iterValue in pairs(v.SpritesheetAnimations) do
				local s2: string = "rbxassetid://" .. iterValue.Image

				if not _CA.t363.Spritesheets[s2] then
					_CA.t363.Spritesheets[s2] = true
					_CA.contentProvider:PreloadAsync({ s2 })
				end

				table.insert(t367, s2)
			end
		end
	end

	_CA.PreloadImages(t367)
end

